export const VERSION='1.0.0',STORAGE_KEY='qf-studio-chapter-08-v1';
export const STEPS=[['start','Freeze the rule',10],['timing','Information before execution',25],['positions','Trace the positions',25],['costs','Account for every trade',30],['benchmark','Compare eligible periods',25],['lab','Run a cost sensitivity',35],['assessment','Independent transfer',20],['finish','Save an execution card',10]];
// Original synthetic positive prices. These observations were authored, not fitted to a market series.
export const DATA=[100,101,102,101,99,98,100,103,104,102,101,105,106,104,107,108].map((close,i)=>({date:`2025-01-${String(i+2).padStart(2,'0')}`,open:[100,100.5,101,103,100,99,97,101,104,103,102,100,106,105,104,108][i],close}));
export const TRANSFER_DATA=[50,51,52,50,49,51,53,52,50,54].map((close,i)=>({date:`2025-02-${String(i+3).padStart(2,'0')}`,open:[50,50,51,53,49,48,52,54,51,50][i],close}));
export const DEVELOPMENT_END='2025-01-17',EVALUATION_START='2025-02-03';
export function backtest(data=DATA,{costBps=10,initial=1000,window=3}={}){
 if(window!==3||typeof costBps!=='number'||!Number.isFinite(costBps)||costBps<0||costBps>100||typeof initial!=='number'||!Number.isFinite(initial)||initial<=0)throw Error('Frozen window=3; use costs 0–100 bps and positive initial wealth.');
 if(!Array.isArray(data)||data.length<5||data.some((r,i)=>typeof r.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||![r.open,r.close].every(x=>typeof x==='number'&&Number.isFinite(x)&&x>0)||(i&&r.date<=data[i-1].date)))throw Error('Use five or more unique chronological ISO-date rows with positive finite open/close prices.');
 const c=costBps/10000;let wealth=initial,benchmark=initial,previous=0;const rows=[];
 for(let t=window-1;t<data.length-2;t++){
  const average=data.slice(t-window+1,t+1).reduce((sum,r)=>sum+r.close,0)/window,position=data[t].close>average?1:0,turnover=Math.abs(position-previous),grossReturn=data[t+2].open/data[t+1].open-1,startWealth=wealth,benchmarkStart=benchmark;
  wealth*=1-c*turnover;wealth*=1+position*grossReturn;
  benchmark*=1-c*(rows.length===0?1:0);benchmark*=1+grossReturn;
  rows.push({signalDate:data[t].date,entryDate:data[t+1].date,exitDate:data[t+2].date,close:data[t].close,average,position,previousPosition:previous,turnover,grossReturn,costRate:c*turnover,startWealth,endWealth:wealth,benchmarkStart,benchmarkEnd:benchmark});previous=position;
 }
 const finalExitCost=wealth*c*previous,benchmarkExitCost=benchmark*c;wealth-=finalExitCost;benchmark-=benchmarkExitCost;
 return {rows,finalWealth:wealth,benchmarkFinal:benchmark,totalReturn:wealth/initial-1,benchmarkReturn:benchmark/initial-1,finalExitCost,benchmarkExitCost,initial,costBps,window};
}
const q=(id,title,answer,hint,critical=false)=>({id,title,answer,hint,critical,tolerance:.011,type:['t2', 'p2', 'b2', 'a2', 'a7', 'a8'].includes(id)?'choice':'number'});
export const PRACTICE={timing:[q('t1','After close Jan 4, the last three closes are 100,101,102. Three-close mean (£)?',101,'(100+101+102)/3=101.'),q('t2','The Jan 4 close is 102>101. Enter 1: execute at the already observed Jan 4 close; 2: execute at Jan 5 open.',2,'Use 2. The decision is made after the signal close.',true)],positions:[q('p1','Eligible first holding interval opens £103→£100, position 1. Gross interval return (%)?',(100/103-1)*100,'100/103−1, then ×100. Never substitute same-day close returns.'),q('p2','If close equals its three-close mean, what position under the frozen strict “above” rule: 0 or 1?',0,'The rule says strictly greater, so equality chooses cash.')],costs:[q('c1','Start £1000, change 0→1, 10 bps costs, then +10% interval return. End wealth (£)?',1098.9,'1000×(1−.001)×1.10 =1098.9.',true),q('c2','Immediately exit that position at 10 bps. Final wealth (£)?',1097.8011,'1098.9×(1−.001). The final exit must be included.',true)],benchmark:[q('b1','Flat price; £1000 buy-and-hold; 10 bps entry and 10 bps final exit. Final (£)?',998.001,'1000×.999×.999, even with no price movement.'),q('b2','Enter 1: benchmark uses all rows including warm-up; 2: benchmark uses the strategy’s same eligible first and last opens.',2,'Use 2. Match holding dates, initial wealth and cost convention.',true)]};
export const ASSESSMENTS=[q('a1','Transfer data: closes 50,51,52. Three-close mean (£)?',51,'153/3=51.'),q('a2','At the third close 52>51, target position: 0 or 1?',1,'Strictly above the trailing mean means fully invested.'),q('a3','That position executes at next open £53 and holds to following open £49. Gross return (%)?',(49/53-1)*100,'49/53−1, multiplied by100.',true),q('a4','£1000 first entry at 20bps then price +5%. Wealth before final exit (£)?',1047.9,'1000×.998×1.05.',true),q('a5','Then exit at 20bps. Final wealth (£)?',1045.8042,'1047.9×.998.',true),q('a6','Reproduce the full transfer table:initial£1000,cost10bps,frozen3-close rule. Strategy final wealth after liquidation (£)?',903.127352687409,'Use each trailing-close signal,next-open interval and every0/1transition,then final liquidation. Reference final£903.127352687409;benchmark£941.5103773584904.',true),q('a7','Enter 1: perturbing future prices may change past positions; 2: past positions must remain unchanged.',2,'Use 2. Only information available through that signal date may enter.',true),q('a8','Enter 1: this teaching run validates a profitable strategy; 2: a trial log, precommitted evaluation and stronger evidence are still needed.',2,'Use 2. Chapters9–10 handle integrity gates; tiny synthetic data establish no investable edge.',true)];
// Exposed teaching segments, not a secure holdout. Ch9 precommit is pedagogical, not access control.
export const DEVELOPMENT_DATA=DATA,EVALUATION_DATA=TRANSFER_DATA,EVALUATION_ID='qf-synthetic-feb2025-v1';

export function check(q,raw){if(typeof raw==='boolean'||raw===null||String(raw??'').trim()==='')return false;const n=Number(raw);return Number.isFinite(n)&&Math.abs(n-q.answer)<=(q.type==='choice'?0:q.tolerance);}
export function grade(answers){const details=ASSESSMENTS.map(q=>({id:q.id,correct:check(q,answers[q.id]),critical:q.critical}));return {score:details.filter(d=>d.correct).length,passed:details.filter(d=>d.correct).length>=7&&details.filter(d=>d.critical).every(d=>d.correct),details};}
export const freshState=()=>({version:VERSION,fields:{},done:{},checked:{},practiceAttempts:[],runs:[],attempts:[]});
export function invalidate(s,id){for(const [step,qs]of Object.entries(PRACTICE))if(qs.some(q=>q.id===id)||id===step+'Reflection'||id===step+'Criteria'){delete s.done[step];delete s.checked[id];}if(id.startsWith('quiz-')||id==='revision'){delete s.done.assessment;s.fields.quizDirty='yes';}if(['prediction','cost','hand','labReflection','labCriteria'].includes(id)){delete s.done.lab;if(id==='hand')s.fields.handVerified='';}if(id.startsWith('card'))delete s.done.finish;if(id==='setup')delete s.done.start;}
export function labEvidence(s){const run=s.runs.at(-1);return String(s.fields.cost??10).trim()!==''&&!!run&&run.prediction===s.fields.prediction&&run.cost===Number(s.fields.cost??10)&&s.runs.some(r=>r.cost!==run.cost)&&check({answer:run.result.rows[0].endWealth,tolerance:.011},s.fields.hand)&&s.fields.handVerified==='yes'&&(s.fields.labReflection||'').trim().length>=50&&s.fields.labCriteria==='yes';}
export function restoreState(raw){try{const s=JSON.parse(raw),record=v=>v&&typeof v==='object'&&!Array.isArray(v);if(s?.version!==VERSION||!record(s.fields)||Object.values(s.fields).some(v=>typeof v!=='string')||!record(s.done)||!record(s.checked)||Object.values(s.done).some(v=>typeof v!=='boolean')||Object.values(s.checked).some(v=>typeof v!=='boolean')||!Array.isArray(s.runs)||!Array.isArray(s.attempts))throw Error();const restored={...freshState(),fields:s.fields,practiceAttempts:(Array.isArray(s.practiceAttempts)?s.practiceAttempts:[]).filter(a=>record(a)&&typeof a.id==='string'&&typeof a.raw==='string'&&typeof a.correct==='boolean'&&typeof a.time==='string'),runs:s.runs.map(r=>{if(typeof r.prediction!=='string'||typeof r.time!=='string')throw Error();return {cost:r.cost,prediction:r.prediction,time:r.time,result:backtest(DATA,{costBps:r.cost})};}),attempts:s.attempts.map(a=>{if(!record(a.answers)||Object.values(a.answers).some(v=>typeof v!=='string')||typeof a.time!=='string'||(a.revision!==undefined&&typeof a.revision!=='string'))throw Error();return {...a,...grade(a.answers)};})};/* Completion is re-derived from current evidence, never accepted from stored booleans. */for(const[step,qs]of Object.entries(PRACTICE)){for(const q of qs)if(s.checked[q.id]===true&&check(q,s.fields[q.id]))restored.checked[q.id]=true;if(qs.every(q=>restored.checked[q.id])&&(s.fields[step+'Reflection']||'').trim().length>=30&&s.fields[step+'Criteria']==='yes')restored.done[step]=true;}if(s.fields.setup==='yes')restored.done.start=true;const latest=restored.attempts.at(-1);if(latest?.passed&&s.fields.quizDirty!=='yes'&&latest.revision?.length>=30&&ASSESSMENTS.every(q=>latest.answers[q.id]===s.fields['quiz-'+q.id]))restored.done.assessment=true;if(['cardMethod','cardCheck','cardLimit'].every(k=>(s.fields[k]||'').trim().length>=30)&&s.fields.cardCriteria==='yes')restored.done.finish=true;if(labEvidence(restored))restored.done.lab=true;return restored;}catch{return freshState();}}
